WITH base AS (
  SELECT "NCT", "Author" AS "Author", "Year", "PubMed ID" AS "PMID", "Cancer type", "Follow-up duration for primary endpoint(s) in months | Overall" AS follow_up_months
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%esophageal%' OR LOWER("Cancer type") LIKE '%gej%'
)
SELECT * FROM base;
